# Heading-aware chunker for a markdown corpus.
#
# Properties that matter here, each one a bug before it was a rule:
#   - A fenced code block is never split. The atomic units are paragraph and whole fenced block;
#     an oversized code block leaves as one oversized chunk rather than a cut one.
#   - Each chunk carries the full heading PATH (H1 > H2 > H3), not the nearest heading.
#   - Lines that look like headings while inside a fence are NOT headings. Bash/Python comments
#     ("# comment", "# Modelfile generated by ...") otherwise cut code blocks open.
#   - load_docs knows nothing about one particular corpus format. A marker-based loader silently
#     returns ZERO documents on a corpus without markers, which surfaces later as a statistics
#     error on empty data, not as a load error.
#
# Use:
#   python chunker.py data/corpus.md            # quality summary; odd_fences MUST be 0
#   from chunker import load_docs, chunk_doc    # use the functions in an ingest script
import pathlib
import re
import statistics
import sys

HEADING = re.compile(r"^(#{1,3})\s+(.*)$")
FENCE = re.compile(r"^\s*```")


def load_docs(path):
    """Read the corpus. Returns [(source_label, body)]. Format-agnostic on purpose."""
    txt = pathlib.Path(path).read_text(encoding="utf-8")
    return [(str(path), txt)]


def load_docs_by_marker(path):
    """Marker-based variant, for corpora that carry `<!-- source: ... -->` markers.

    Check the count first: grep -c '<!-- source' corpus.md. On a corpus with none this returns
    an empty list, and nothing downstream says 'zero documents loaded'.
    """
    txt = pathlib.Path(path).read_text(encoding="utf-8")
    parts = re.split(r"<!-- source: ([^ ]+) -->", txt)
    return [(parts[i], parts[i + 1]) for i in range(1, len(parts) - 1, 2)]


def heading_path(head):
    parts = [head.get(1, ""), head.get(2, ""), head.get(3, "")]
    return " > ".join(p for p in parts if p) or "(intro)"


def sections(body):
    """Split into (heading_path, text), ignoring heading-like lines inside code fences."""
    out, head, buf, in_fence = [], {}, [], False
    for line in body.splitlines(keepends=True):
        if FENCE.match(line):
            in_fence = not in_fence
            buf.append(line)
            continue
        m = HEADING.match(line) if not in_fence else None
        if m:
            if buf:
                out.append((heading_path(head), "".join(buf)))
                buf = []
            level, title = len(m.group(1)), m.group(2).strip()
            head = {k: v for k, v in head.items() if k < level}   # drop deeper headings
            head[level] = title
            continue
        buf.append(line)
    if buf:
        out.append((heading_path(head), "".join(buf)))
    return out


def units(text):
    """Atomic units: ('para', text) or ('fence', text). A fence always comes out whole."""
    out, para, fence, in_fence = [], [], [], False
    for line in text.splitlines(keepends=True):
        if FENCE.match(line):
            if not in_fence:
                t = "".join(para).strip()
                if t:
                    out.append(("para", t))
                para = []
                in_fence, fence = True, [line]
            else:
                fence.append(line)
                in_fence = False
                out.append(("fence", "".join(fence).strip()))
            continue
        if in_fence:
            fence.append(line)
            continue
        if not line.strip():
            t = "".join(para).strip()
            if t:
                out.append(("para", t))
            para = []
            continue
        para.append(line)
    if in_fence:
        out.append(("fence", "".join(fence).strip()))   # unterminated fence stays whole
    t = "".join(para).strip()
    if t:
        out.append(("para", t))
    return out


def chunk_doc(src, body, target=700, overlap=250, min_len=80):
    """Chunk per heading section, packing atomic units up to ~target characters.

    target   characters per chunk
    overlap  a short trailing paragraph repeated at the start of the next chunk so an idea
             spanning a boundary survives; never a code block
    """
    chunks = []
    for spath, stext in sections(body):
        buf, blen = [], 0
        for _kind, text in units(stext):
            if buf and blen + len(text) > target:
                chunks.append((spath, "\n\n".join(buf)))
                last = buf[-1]
                carry = [last] if len(last) <= overlap and not last.lstrip().startswith("```") else []
                buf, blen = list(carry), sum(len(x) + 2 for x in carry)
            buf.append(text)
            blen += len(text) + 2
        if buf:
            chunks.append((spath, "\n\n".join(buf)))
    return [(src, h, i, t) for i, (h, t) in enumerate(c for c in chunks if len(c[1]) >= min_len)]


def summary(chunks):
    lens = sorted(len(c[3]) for c in chunks)
    return {
        "chunks": len(chunks),
        "median_chars": int(statistics.median(lens)) if lens else 0,
        "min_chars": lens[0] if lens else 0,
        "max_chars": lens[-1] if lens else 0,   # above target is expected: whole code blocks
        "no_heading": sum(1 for c in chunks if c[1] == "(intro)"),
        # MUST be 0: an odd number of fence markers means a code block was cut in half
        "odd_fences": sum(1 for c in chunks if c[3].count("```") % 2),
        "distinct_headings": len({c[1] for c in chunks}),
    }


if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else "data/corpus.md"
    chunks = [c for src, body in load_docs(path) for c in chunk_doc(src, body)]
    s = summary(chunks)
    for k, v in s.items():
        print(f"{k:18} {v}")
    print("OK: no split code block" if not s["odd_fences"]
          else "FAIL: a code block was split; fix the fence handling before continuing")
    if s["chunks"] > 20 and s["distinct_headings"] == 1:
        print("SUSPECT: every chunk shares one heading path "
              "(heading captured at flush time instead of per section)")
    if chunks:
        mid = chunks[len(chunks) // 2]
        print("example:", mid[1], "|", mid[3][:70].replace("\n", " "))
